        check_output(1'b0); // Cycle 5
        check_output(1'b0); // Cycle 6
        check_output(1'b0); // Cycle 7

        // Test 2: Apply reset again to verify it repeats the 4-cycle behavior
        @(posedge clk);
        reset = 1;
        #1;
        if (shift_ena !== 1'b1) begin
            $display("Time %0t: Second reset cycle 1 error", $time);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;

        check_output(1'b1); // Cycle 1
        check_output(1'b1); // Cycle 2
        check_output(1'b1); // Cycle 3
        check_output(1'b1); // Cycle 4
        check_output(1'b0); // Cycle 5
        check_output(1'b0); // Cycle 6

        // Final status report
        #20;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
